import "core-js/modules/es.array.push.js";
import OverlayComp from "@/components/OverlayComp.vue";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import EditDashboarddetails from "@/components/DashBoard/Popups/EditDashboarddetails.vue";
import { format_Date } from "@/JsonFiles/DateFormate.js";
import SnackBar from "@/components/SnackBar.vue";
import { API, graphqlOperation } from "aws-amplify";
import { get_particular_dashboard } from "@/graphql/queries.js";
export default {
  mixins: [get_all_org_users],
  components: {
    SnackBar,
    EditDashboarddetails,
    OverlayComp
  },
  data() {
    return {
      SnackBarComponent: {},
      componentCheck: 0,
      dashboardName: "",
      dashboardDescription: "",
      dashboardfeeedtype: "",
      dashboard_frequency: "",
      dashboardsubcount: "",
      dashboardvisibility: "",
      dashboardcreatedon: "",
      dashboardcreatedby: "",
      feedAccountid: "",
      feedAccountemailid: "",
      feedAccountname: "",
      allUsers: [],
      dashboardedition: false,
      overlay: false,
      detailsdashboard: {}
    };
  },
  async mounted() {
    this.overlay = true;
    await this.get_all_org_users();
    this.allUsers = this.orgUsers;
    await this.get_dashboard_details();
    this.overlay = false;
  },
  methods: {
    convertToTimeZone(time) {
      let [hours, minutes] = time.split(":");
      let date = new Date();
      date.setUTCHours(parseInt(hours));
      date.setUTCMinutes(parseInt(minutes));
      let options = {
        // timeZone: "Asia/Kolkata",
        timeZone: this.$store.getters.GetOrgDetails.organization.default_timezone,
        hour: "2-digit",
        minute: "2-digit",
        hour12: true // 24-hour format
      };
      return new Intl.DateTimeFormat("en-US", options).format(date);
    },
    async get_dashboard_details() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(get_particular_dashboard, {
          input: {
            dashboard_id: this.$store.getters.GetdashboardDetails.dashboard_id
          }
        }));
        var response = JSON.parse(result.data.get_particular_dashboard);
        this.tableLoading = false;
        if (response.Status == "SUCCESS" && response.data && response.data.length > 0) {
          var data = response.data[0];
          this.detailsdashboard = response.data[0];
          this.dashboardName = data.dashboard_name || "";
          this.dashboardDescription = data.dashboard_description || "";
          this.dashboardsubcount = data.subscribe_counts || 0;

          // Safe handling of dashboard_visibility
          try {
            this.dashboardvisibility = data.dashboard_visibility && data.dashboard_visibility.visible_type == "RESTRICTED_MEMBERS" ? "Restricted Users" + " " + "(" + this.fetch_names(data.dashboard_visibility.visible_members || []) + ")" : "All Members";
          } catch (error) {
            console.warn("Error processing dashboard visibility:", error);
            this.dashboardvisibility = "All Members";
          }
          this.dashboardcreatedon = data.dashboard_created_on || "";
          this.dashboardcreatedby = data.dashboard_created_by || "";
          this.dashboardfeeedtype = data.dashboard_feed_type == undefined ? "" : data.dashboard_feed_type;
          this.dashboard_frequency = data.dashboard_publish_frequency == undefined ? "" : data.dashboard_publish_frequency;
          this.feedAccountid = data.dashboard_account_details == undefined ? "" : data.dashboard_account_details.account_id;
          this.feedAccountemailid = data.dashboard_account_details == undefined ? "" : data.dashboard_account_details.account_email_id;
          this.feedAccountname = data.dashboard_account_details == undefined ? "" : data.dashboard_account_details.account_name;
          this.$store.commit("SetdashboardDetails", data);
        } else {
          console.warn("No dashboard data available");
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "orange",
            SnackbarText: "No dashboard data available",
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        console.log(error);
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    fetch_value(val) {
      return format_Date(val);
    },
    fetch_names(ids) {
      var names = [];
      if (!ids || !Array.isArray(ids)) {
        return names;
      }
      for (var i = 0; i < ids.length; i++) {
        var id = ids[i];
        for (var j = 0; j < this.allUsers.length; j++) {
          if (this.allUsers[j].user_id === id) {
            names.push(this.allUsers[j].full_user_name);
            break; // Break the inner loop once match is found
          }
        }
      }
      return names;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.dashboardedition = false;
      this.get_dashboard_details();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    edit_dashboard_details() {
      this.componentCheck = 1;
      this.dashboardedition = true;
    }
  }
};
